const {createRequire}=require('node:module');
const require=createRequire(process.env.HOME+'/.local/share/omgithub-playwright/package.json');
const {chromium}=require('playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1280,height:900},deviceScaleFactor:1});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.addInitScript(()=>localStorage.setItem('emberbound-save',JSON.stringify({gold:1000,stage:1,kills:0,hp:60,maxHp:60,upgrade:{blade:0,ranger:0,familiar:0},tap:5,dps:0,hero:1,last:Date.now(),tab:'forge',relics:0,questClaimed:false})));
 await page.goto('http://127.0.0.1:3000',{waitUntil:'load'});
 await page.getByRole('button',{name:'×10'}).click();
 const before=JSON.parse(await page.evaluate(()=>localStorage.getItem('emberbound-save')));
 await page.locator('#upgrades .upgrade').nth(0).click();
 const after=JSON.parse(await page.evaluate(()=>localStorage.getItem('emberbound-save')));
 if(after.upgrade.blade!==10||!(after.gold<before.gold))throw Error(`×10 failed: ${JSON.stringify({before:before.gold,after:after.gold,blade:after.upgrade.blade})}`);
 await page.getByRole('button',{name:'MAX'}).click();
 const maxCost=await page.locator('#upgrades .upgrade').nth(1).locator('.upgrade-cost').innerText();
 await page.locator('#upgrades .upgrade').nth(1).click();
 const maxAfter=JSON.parse(await page.evaluate(()=>localStorage.getItem('emberbound-save')));
 if(maxAfter.upgrade.ranger<=0)throw Error('MAX did not purchase an affordable Ranger');
 await page.screenshot({path:'screenshots/emberbound-quantity.jpg',type:'jpeg',quality:78,fullPage:false});
 console.log(JSON.stringify({x10Blade:after.upgrade.blade,x10GoldSpent:before.gold-after.gold,maxPreview:maxCost,maxRangerLevel:maxAfter.upgrade.ranger,pageErrors:errors,screenshot:'screenshots/emberbound-quantity.jpg'}));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
